changeSet.sql:
-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_member_reference ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_member_reference FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_member_reference_tenant ON zc_member_reference
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_external_reference ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_external_reference FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_external_reference_tenant ON zc_external_reference
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_member_reference_tenant ON zc_member_reference;
ALTER TABLE zc_member_reference NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_member_reference DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_external_reference_tenant ON zc_external_reference;
ALTER TABLE zc_external_reference NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_external_reference DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_member_reference TO zc_app;
GRANT USAGE ON SEQUENCE zc_member_reference_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_external_reference TO zc_app;
GRANT USAGE ON SEQUENCE zc_external_reference_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_member_reference FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_member_reference_id_seq FROM zc_app;
REVOKE ALL ON zc_external_reference FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_external_reference_id_seq FROM zc_app;
